[metadata] {"type": "create", "filePath": "/app/output/food_waste_viz.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Food Waste Supply Chain: Climate &amp; Intervention Analysis</title>
<link href="https://fonts.googleapis.com/css2?family=Crimson+Pro:ital,wght@0,300;0,400;0,600;0,700;1,400&family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@300;400;500;600&display=swap" rel="stylesheet">
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
:root {
  --bg: #faf8f4;
  --surface: #ffffff;
  --surface-alt: #f5f1ea;
  --border: rgba(0,0,0,0.10);
  --border-strong: rgba(0,0,0,0.18);
  --text: #1c1a17;
  --text-dim: #6b6355;
  --text-faint: #9e9585;

  /* Stage colors — earthy, editorial */
  --c-production: #b5451b;
  --c-processing: #c8862a;
  --c-retail: #4a7c59;
  --c-consumption: #2c5f8a;

  --c-production-dim: rgba(181,69,27,0.15);
  --c-processing-dim: rgba(200,134,42,0.15);
  --c-retail-dim: rgba(74,124,89,0.15);
  --c-consumption-dim: rgba(44,95,138,0.15);

  --c-avoidable: #d4a73a;
  --c-carbon: #7a3b2e;
  --c-priority: #8b1f3f;

  --font-serif: 'Crimson Pro', Georgia, serif;
  --font-sans: 'IBM Plex Sans', system-ui, sans-serif;
  --font-mono: 'IBM Plex Mono', monospace;

  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.07), 0 2px 4px rgba(0,0,0,0.04);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: var(--bg);
  background-image:
    linear-gradient(rgba(0,0,0,0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0,0,0,0.025) 1px, transparent 1px);
  background-size: 40px 40px;
  font-family: var(--font-sans);
  color: var(--text);
  min-height: 100vh;
  padding: 48px 24px 80px;
}

.page-wrap {
  max-width: 1280px;
  margin: 0 auto;
}

/* ── MASTHEAD ── */
.masthead {
  margin-bottom: 52px;
  border-bottom: 2px solid var(--border-strong);
  padding-bottom: 32px;
}
.masthead-kicker {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--c-carbon);
  margin-bottom: 10px;
}
.masthead h1 {
  font-family: var(--font-serif);
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 600;
  line-height: 1.15;
  color: var(--text);
  max-width: 800px;
  margin-bottom: 14px;
}
.masthead-sub {
  font-size: 15px;
  color: var(--text-dim);
  max-width: 680px;
  line-height: 1.6;
  font-weight: 300;
}
.masthead-meta {
  margin-top: 18px;
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
}
.meta-pill {
  font-family: var(--font-mono);
  font-size: 10.5px;
  letter-spacing: 0.06em;
  color: var(--text-faint);
  background: var(--surface-alt);
  border: 1px solid var(--border);
  padding: 3px 9px;
  border-radius: 2px;
}

/* ── STAGE LEGEND ── */
.stage-legend {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  margin-bottom: 40px;
}
.stage-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--font-sans);
  font-size: 12.5px;
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--text);
}
.stage-dot {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  flex-shrink: 0;
}

/* ── SECTION LABEL ── */
.section-label {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-faint);
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.section-label::before {
  content: '';
  display: inline-block;
  width: 20px;
  height: 1px;
  background: currentColor;
}
.section-title {
  font-family: var(--font-serif);
  font-size: clamp(18px, 2.5vw, 26px);
  font-weight: 600;
  line-height: 1.2;
  color: var(--text);
  margin-bottom: 6px;
}
.section-desc {
  font-size: 13.5px;
  color: var(--text-dim);
  margin-bottom: 24px;
  line-height: 1.5;
  max-width: 660px;
  font-weight: 300;
}

/* ── CARDS ── */
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 3px;
  padding: 28px;
  box-shadow: var(--shadow-sm);
}
.card-title {
  font-family: var(--font-serif);
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 4px;
}
.card-sub {
  font-size: 12px;
  color: var(--text-faint);
  font-family: var(--font-mono);
  margin-bottom: 18px;
}

/* ── GRID LAYOUTS ── */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.span-2 { grid-column: span 2; }

@media (max-width: 900px) {
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .span-2 { grid-column: span 1; }
}

/* ── SECTION BREAK ── */
.section-break {
  margin: 56px 0 36px;
}

/* ── CHART CONTAINERS ── */
.chart-wrap {
  position: relative;
  width: 100%;
}
.chart-wrap canvas { display: block; }

/* ── PRIORITY SIGNAL ── */
.priority-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}
@media (max-width: 800px) {
  .priority-grid { grid-template-columns: repeat(2, 1fr); }
}
.priority-card {
  border-radius: 3px;
  padding: 18px;
  border: 1.5px solid var(--border);
  position: relative;
  overflow: hidden;
}
.priority-card::after {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
}
.pc-production { background: var(--c-production-dim); }
.pc-production::after { background: var(--c-production); }
.pc-processing { background: var(--c-processing-dim); }
.pc-processing::after { background: var(--c-processing); }
.pc-retail { background: var(--c-retail-dim); }
.pc-retail::after { background: var(--c-retail); }
.pc-consumption { background: var(--c-consumption-dim); }
.pc-consumption::after { background: var(--c-consumption); }

.priority-stage {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-bottom: 8px;
}
.priority-score-label {
  font-family: var(--font-sans);
  font-size: 11px;
  color: var(--text-faint);
  margin-bottom: 2px;
}
.priority-score {
  font-family: var(--font-serif);
  font-size: 32px;
  font-weight: 700;
  line-height: 1;
  margin-bottom: 12px;
}
.priority-bar-wrap {
  background: rgba(0,0,0,0.06);
  border-radius: 1px;
  height: 4px;
  margin-bottom: 10px;
}
.priority-bar {
  height: 100%;
  border-radius: 1px;
  transition: width 1s ease;
}
.priority-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  margin-top: 10px;
}
.ps-item {
  font-size: 11px;
}
.ps-label { color: var(--text-faint); font-family: var(--font-mono); font-size: 9.5px; text-transform: uppercase; letter-spacing: 0.06em; }
.ps-val { font-weight: 600; font-size: 12.5px; color: var(--text); }

/* Priority badge */
.priority-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 2px 6px;
  border-radius: 1px;
  margin-top: 8px;
}
.badge-high { background: var(--c-priority); color: #fff; }
.badge-medium { background: #c8862a; color: #fff; }
.badge-standard { background: var(--surface-alt); color: var(--text-dim); border: 1px solid var(--border); }

/* ── REGIONAL HEATMAP TABLE ── */
.heatmap-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.heatmap-table th {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-faint);
  padding: 8px 12px;
  text-align: left;
  border-bottom: 1px solid var(--border-strong);
}
.heatmap-table th:not(:first-child) { text-align: center; }
.heatmap-table td {
  padding: 7px 12px;
  border-bottom: 1px solid var(--border);
  vertical-align: middle;
}
.heatmap-table td:first-child {
  font-weight: 500;
  font-size: 12.5px;
  white-space: nowrap;
}
.heatmap-table td:not(:first-child) { text-align: center; }
.heatmap-table tr:last-child td { border-bottom: none; font-weight: 600; background: var(--surface-alt); }

.heat-cell {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  min-width: 62px;
}
.heat-val { font-weight: 600; font-size: 13px; }
.heat-bar-outer {
  width: 48px;
  height: 3px;
  background: rgba(0,0,0,0.07);
  border-radius: 1px;
  overflow: hidden;
}
.heat-bar-inner {
  height: 100%;
  border-radius: 1px;
}
.heat-avoid {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-faint);
}

/* ── ANNOTATIONS ── */
.annotation-note {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-dim);
  border-left: 2px solid var(--border-strong);
  padding: 8px 12px;
  margin-top: 12px;
  line-height: 1.5;
}

/* ── FOOTER ── */
.page-footer {
  margin-top: 60px;
  padding-top: 20px;
  border-top: 1px solid var(--border);
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-faint);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
}

/* ── ANIMATIONS ── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(18px); }
  to   { opacity: 1; transform: translateY(0); }
}
.anim { opacity: 0; animation: fadeUp 0.5s ease forwards; }
.a1 { animation-delay: 0.05s; }
.a2 { animation-delay: 0.12s; }
.a3 { animation-delay: 0.20s; }
.a4 { animation-delay: 0.28s; }
.a5 { animation-delay: 0.36s; }
.a6 { animation-delay: 0.44s; }
.a7 { animation-delay: 0.52s; }

@media (prefers-reduced-motion: reduce) {
  .anim { opacity: 1; animation: none; }
}
