<script>
// ── DATA ──
const stages = ['Production','Processing','Retail','Consumption'];
const stageColors = ['#b5451b','#c8862a','#4a7c59','#2c5f8a'];
const stageColorsDim = ['rgba(181,69,27,0.18)','rgba(200,134,42,0.18)','rgba(74,124,89,0.18)','rgba(44,95,138,0.18)'];

const regions = ['North America & Oceania','Europe','Sub-Saharan Africa','South & Southeast Asia','Latin America','Global Average'];

const wasteByStageRegion = {
  'North America & Oceania': {Production:12.0, Processing:8.5, Retail:11.0, Consumption:68.5},
  'Europe': {Production:14.0, Processing:10.0, Retail:12.5, Consumption:63.5},
  'Sub-Saharan Africa': {Production:39.0, Processing:28.0, Retail:19.0, Consumption:14.0},
  'South & Southeast Asia': {Production:32.0, Processing:24.0, Retail:18.0, Consumption:26.0},
  'Latin America': {Production:28.0, Processing:19.0, Retail:17.0, Consumption:36.0},
  'Global Average': {Production:24.0, Processing:18.0, Retail:15.0, Consumption:43.0}
};

const carbonByStage = {Production:{pct:30.5, mt:1372}, Processing:{pct:22.0, mt:990}, Retail:{pct:16.5, mt:742}, Consumption:{pct:31.0, mt:1395}};

const avoidByStageRegion = {
  'North America & Oceania': {Production:55, Processing:70, Retail:78, Consumption:62},
  'Europe': {Production:58, Processing:72, Retail:80, Consumption:65},
  'Sub-Saharan Africa': {Production:75, Processing:68, Retail:50, Consumption:30},
  'South & Southeast Asia': {Production:72, Processing:65, Retail:52, Consumption:40},
  'Latin America': {Production:68, Processing:60, Retail:58, Consumption:48},
  'Global Average': {Production:65, Processing:67, Retail:64, Consumption:52}
};

const interventionData = {
  Production: {food:210, co2:890, interventions:'Improved harvesting, cold chain, farmer training'},
  Processing: {food:155, co2:665, interventions:'Process optimization, byproduct valorization'},
  Retail: {food:120, co2:475, interventions:'Dynamic pricing, inventory management, donation programs'},
  Consumption: {food:280, co2:725, interventions:'Portion awareness, date labeling reform, composting'}
};

// ── CHART DEFAULTS ──
Chart.defaults.font.family = "'IBM Plex Sans', system-ui, sans-serif";
Chart.defaults.font.size = 12;
Chart.defaults.color = '#6b6355';

function noGrid(axis) {
  return { grid: { color: 'rgba(0,0,0,0.05)', drawBorder: false }, border: { dash: [3,3] }, ...axis };
}

// ── CHART 1: Waste Share (donut) ──
(function() {
  const ctx = document.getElementById('chart-waste-share').getContext('2d');
  const g = wasteByStageRegion['Global Average'];
  new Chart(ctx, {
    type: 'doughnut',
    data: {
      labels: stages,
      datasets: [{
        data: stages.map(s => g[s]),
        backgroundColor: stageColors,
        borderWidth: 2,
        borderColor: '#ffffff'
      }]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      cutout: '60%',
      plugins: {
        legend: { position: 'right', labels: { boxWidth: 11, padding: 14, font: {size:12} } },
        tooltip: {
          callbacks: { label: ctx => ` ${ctx.label}: ${ctx.parsed}%` }
        }
      }
    }
  });
})();

// ── CHART 2: Carbon Share (donut) ──
(function() {
  const ctx = document.getElementById('chart-carbon-share').getContext('2d');
  new Chart(ctx, {
    type: 'doughnut',
    data: {
      labels: stages,
      datasets: [{
        data: stages.map(s => carbonByStage[s].pct),
        backgroundColor: stageColors,
        borderWidth: 2,
        borderColor: '#ffffff'
      }]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      cutout: '60%',
      plugins: {
        legend: { position: 'right', labels: { boxWidth: 11, padding: 14, font: {size:12} } },
        tooltip: {
          callbacks: { label: ctx => ` ${ctx.label}: ${ctx.parsed}% (${carbonByStage[stages[ctx.dataIndex]].mt} Mt CO₂e)` }
        }
      }
    }
  });
})();

// ── CHART 3: Divergence Bar ──
(function() {
  const ctx = document.getElementById('chart-divergence').getContext('2d');
  const g = wasteByStageRegion['Global Average'];
  const divergence = stages.map(s => +(carbonByStage[s].pct - g[s]).toFixed(1));
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: stages,
      datasets: [{
        label: 'Carbon % − Waste %',
        data: divergence,
        backgroundColor: divergence.map(v => v > 0 ? 'rgba(181,69,27,0.75)' : 'rgba(44,95,138,0.55)'),
        borderColor: divergence.map(v => v > 0 ? '#b5451b' : '#2c5f8a'),
        borderWidth: 1.5,
        borderRadius: 2
      }]
    },
    options: {
      responsive: true, maintainAspectRatio: false, indexAxis: 'y',
      plugins: {
        legend: { display: false },
        tooltip: { callbacks: { label: ctx => ` ${ctx.parsed.x > 0 ? '+' : ''}${ctx.parsed.x} pp` } }
      },
      scales: {
        x: noGrid({ title: { display: true, text: 'Percentage point difference', font: {size:11} } }),
        y: { grid: { display: false }, border: { display: false } }
      }
    }
  });
})();

// ── CHART 4: Avoidable Waste Grouped Bar ──
(function() {
  const ctx = document.getElementById('chart-avoidable').getContext('2d');
  const displayRegions = regions.filter(r => r !== 'Global Average');
  const regionColors = ['#b5451b','#c8862a','#4a7c59','#2c5f8a','#7a3b2e'];

  const datasets = displayRegions.map((r, i) => ({
    label: r,
    data: stages.map(s => avoidByStageRegion[r][s]),
    backgroundColor: regionColors[i].replace(')', ',0.7)').replace('rgb', 'rgba').replace('#', ''),
    backgroundColor: regionColors[i] + 'b3',
    borderColor: regionColors[i],
    borderWidth: 1.5,
    borderRadius: 2
  }));

  new Chart(ctx, {
    type: 'bar',
    data: { labels: stages, datasets },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { position: 'bottom', labels: { boxWidth: 10, padding: 12, font: {size:10.5} } },
        tooltip: { callbacks: { label: ctx => ` ${ctx.dataset.label}: ${ctx.parsed.y}% avoidable` } }
      },
      scales: {
        x: { grid: { display: false }, border: { display: false } },
        y: noGrid({ min: 0, max: 100, ticks: { callback: v => v + '%' }, title: { display: true, text: 'Avoidable %', font:{size:11} } })
      }
    }
  });
})();

// ── CHART 5: Bubble — Avoidable vs Carbon, bubble=food saved ──
(function() {
  const ctx = document.getElementById('chart-bubble').getContext('2d');
  const g = wasteByStageRegion['Global Average'];
  const data = stages.map((s, i) => ({
    x: avoidByStageRegion['Global Average'][s],
    y: carbonByStage[s].pct,
    r: Math.sqrt(interventionData[s].food) * 1.2,
    stage: s, color: stageColors[i]
  }));

  new Chart(ctx, {
    type: 'bubble',
    data: {
      datasets: data.map(d => ({
        label: d.stage,
        data: [{ x: d.x, y: d.y, r: d.r }],
        backgroundColor: d.color + '88',
        borderColor: d.color,
        borderWidth: 2
      }))
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { position: 'bottom', labels: { boxWidth: 10, padding: 12, font: {size:11} } },
        tooltip: {
          callbacks: {
            label: ctx => {
              const s = ctx.dataset.label;
              return [` ${s}`, ` Avoidable: ${ctx.parsed.x}%`, ` Carbon share: ${ctx.parsed.y}%`, ` Food saveable: ${interventionData[s].food} Mt`];
            }
          }
        }
      },
      scales: {
        x: noGrid({ min: 40, max: 85, title: { display: true, text: 'Avoidable waste % (global avg)', font:{size:11} } }),
        y: noGrid({ title: { display: true, text: 'Carbon emission share %', font:{size:11} } })
      }
    }
  });
})();

// ── REGIONAL HEATMAP TABLE ──
(function() {
  const tbody = document.getElementById('heatmap-body');
  const displayRegions = [...regions.slice(0,5), 'Global Average'];
  displayRegions.forEach(region => {
    const tr = document.createElement('tr');
    const shortName = region.replace(' & Oceania', '').replace('South & Southeast ', 'S&SE ');
    tr.innerHTML = `<td>${region === 'Global Average' ? '<em>Global Average</em>' : shortName}</td>`;
    stages.forEach((s, i) => {
      const w = wasteByStageRegion[region][s];
      const a = avoidByStageRegion[region][s];
      const pct = Math.round(w);
      const barWidth = Math.round(w);
      tr.innerHTML += `<td>
        <div class="heat-cell">
          <span class="heat-val">${pct}%</span>
          <div class="heat-bar-outer"><div class="heat-bar-inner" style="width:${barWidth}%;background:${stageColors[i]}"></div></div>
          <span class="heat-avoid">↑${a}% avoid.</span>
        </div>
      </td>`;
    });
    tbody.appendChild(tr);
  });
})();

// ── CHART 6: Regional Stacked Bar ──
(function() {
  const ctx = document.getElementById('chart-regional').getContext('2d');
  const displayRegions = ['North America & Oceania','Europe','Sub-Saharan Africa','South & Southeast Asia','Latin America','Global Average'];
  const shortLabels = ['N. America\n& Oceania','Europe','Sub-Saharan\nAfrica','S&SE\nAsia','Latin\nAmerica','Global\nAvg'];

  const datasets = stages.map((s, i) => ({
    label: s,
    data: displayRegions.map(r => wasteByStageRegion[r][s]),
    backgroundColor: stageColors[i],
    borderColor: '#fff',
    borderWidth: 1.5
  }));

  new Chart(ctx, {
    type: 'bar',
    data: { labels: displayRegions.map(r => r.replace(' & Oceania','').replace('South & Southeast','S&SE')), datasets },
