// ── PRIORITY CARDS ──
(function() {
  const container = document.getElementById('priority-cards');
  // Priority score = (carbon_pct × avoidable_pct) / 1000 normalized
  const scores = stages.map(s => {
    const avoid = avoidByStageRegion['Global Average'][s];
    const carbon = carbonByStage[s].pct;
    const wasteShare = wasteByStageRegion['Global Average'][s];
    return { stage: s, score: (avoid * carbon) / 100, avoid, carbon, wasteShare, food: interventionData[s].food, co2: interventionData[s].co2 };
  });
  const maxScore = Math.max(...scores.map(x => x.score));

  scores.forEach((d, i) => {
    const pct = Math.round(d.score / maxScore * 100);
    const badge = pct >= 85 ? ['HIGH PRIORITY','badge-high'] : pct >= 65 ? ['MED–HIGH','badge-medium'] : ['STANDARD','badge-standard'];
    const cls = ['pc-production','pc-processing','pc-retail','pc-consumption'][i];
    const card = document.createElement('div');
    card.className = `priority-card ${cls}`;
    card.innerHTML = `
      <div class="priority-stage" style="color:${stageColors[i]}">${d.stage}</div>
      <div class="priority-score-label">Composite priority index</div>
      <div class="priority-score" style="color:${stageColors[i]}">${pct}</div>
      <div class="priority-bar-wrap">
        <div class="priority-bar" style="width:${pct}%;background:${stageColors[i]}"></div>
      </div>
      <div class="priority-stats">
        <div class="ps-item"><div class="ps-label">Avoidable</div><div class="ps-val">${d.avoid}%</div></div>
        <div class="ps-item"><div class="ps-label">Carbon share</div><div class="ps-val">${d.carbon}%</div></div>
        <div class="ps-item"><div class="ps-label">Food save</div><div class="ps-val">${d.food} Mt</div></div>
        <div class="ps-item"><div class="ps-label">CO₂ avoid</div><div class="ps-val">${d.co2} Mt</div></div>
      </div>
      <span class="priority-badge ${badge[1]}">${badge[0]}</span>
    `;
    container.appendChild(card);
  });
})();

